 const ticket:TicketData|undefined=data?.ticket;
 async function change(values:AnyData){if(!ticket)return;setBusy(true);try{await api('tickets/'+id,{method:'PATCH',body:JSON.stringify({version:ticket.version,...values})});await refresh();onChange();notice('Ticket updated.');}catch(e){setError((e as Error).message);await refresh();}finally{setBusy(false);}}
 async function send(e:React.FormEvent){e.preventDefault();setBusy(true);setError('');try{await api('tickets/'+id+'/messages',{method:'POST',body:JSON.stringify({body,private:internal,clientId:draftId.current,attachmentIds:attachments.map(a=>a.id),mentionIds:mention?[mention]:[]})});setBody('');setAttachments([]);draftId.current=crypto.randomUUID();setMention('');await refresh();onChange();}catch(e){setError((e as Error).message);}finally{setBusy(false);}}
 async function upload(file:File){setBusy(true);try{if(file.size>5*1024*1024)throw new Error('Attachments must be 5 MB or smaller.');const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));const a=await api('tickets/'+id+'/attachments',{method:'POST',body:JSON.stringify({fileName:file.name,mime:file.type,data:btoa(binary),private:internal})});setAttachments(previous=>[...previous,a]);}catch(e){setError((e as Error).message);}finally{setBusy(false);}}
