function Reports({data,online}:{data:AnyData|null;online:boolean}){return <><div className="report-heading"><Tag>Workspace-wide service metrics</Tag><a className={'button '+(!online?'disabled':'')} href={online?'/api/support/export':undefined}><Download size={15}/>Export CSV</a></div><div className="metrics-grid">{[['Ticket volume',data?.volume],['Active backlog',data?.backlog],['SLA compliance',data?.slaCompliance==null?'—':data.slaCompliance.toFixed(1)+'%'],['Customer satisfaction',data?.satisfaction==null?'—':data.satisfaction.toFixed(1)+' / 5']].map(([label,value])=><div className="metric" key={label}><div className="metric-top">{label}</div><strong>{value??'—'}</strong><p>{data?'Persisted workspace records':'Live data not connected'}</p></div>)}</div><div className="reports-grid"><div className="panel report-panel"><h2>Requests by support tier</h2><p>Your support mix, at a glance.</p>{[...tiers].reverse().map(t=><div className="report-bar" key={t}><span>{tierInfo[t].name}</span><div><i style={{width:data?.volume?`${data.byTier[t]/data.volume*100}%`:'0%',background:tierInfo[t].color}}/></div><strong>{data?.byTier[t]??'—'}</strong></div>)}</div><div className="panel report-panel"><h2>Service performance</h2>{[['Average first response',data?.averageResponseMinutes==null?'—':data.averageResponseMinutes.toFixed(1)+' min'],['Average resolution',data?.averageResolutionHours==null?'—':data.averageResolutionHours.toFixed(1)+' hrs'],['Recorded SLA breaches',data?.breaches??'—'],['Failed dispatch jobs',data?.outboxFailures??'—']].map(([label,value])=><div className="performance-line" key={label}><span>{label}</span><strong>{value}</strong></div>)}<p className="muted">Elapsed averages include time outside business hours. SLA compliance uses each stored policy deadline.</p>{data?.truncated&&<p className="error-inline">Report is limited to 10,000 records. Use a reporting pipeline for larger datasets.</p>}</div></div></>;}
function ContentForm({title,category=false,onClose,onSave}:{title:string;category?:boolean;onClose:()=>void;onSave:(v:AnyData)=>Promise<void>}){const [busy,setBusy]=useState(false),[error,setError]=useState('');return <Modal title={title} onClose={onClose}><form className="ticket-form" onSubmit={async e=>{e.preventDefault();const form=new FormData(e.currentTarget);setBusy(true);try{await onSave({title:String(form.get('title')),body:String(form.get('body')),...(category?{category:String(form.get('category')),published:form.get('published')==='on'}:{})});}catch(e){setError((e as Error).message);}finally{setBusy(false);}}}><label className="field">Title<input name="title" required minLength={3}/></label>{category&&<label className="field">Category<input name="category" required defaultValue="Getting started"/></label>}<label className="field">Content<textarea name="body" rows={8} required maxLength={12000}/></label>{category&&<label className="check-field"><input name="published" type="checkbox"/>Publish for customers</label>}{error&&<div className="error-inline">{error}</div>}<div className="form-actions"><button className="button primary" disabled={busy} type="submit">{busy?'Saving…':'Save'}</button></div></form></Modal>;}
function AdminSettings({data,online,notice,reload}:{data:AnyData|null;online:boolean;notice:(s:string)=>void;reload:()=>Promise<any>}){
 const [settings,setSettings]=useState<AnyData|null>(null),[tab,setTab]=useState('Service policies'),[busy,setBusy]=useState(false),[create,setCreate]=useState('');useEffect(()=>{setSettings(data?.workspace.settings||null);},[data]);
 async function save(e:React.FormEvent){e.preventDefault();if(!data||!settings)return;setBusy(true);try{await api('admin/settings',{method:'PATCH',body:JSON.stringify({version:data.workspace.version,settings:{...settings,configured:true}})});await reload();notice('Service settings saved. Existing ticket policies are preserved.');}catch(e){notice((e as Error).message);}finally{setBusy(false);}}
 return <div className="panel settings-panel"><div className="detail-tabs">{['Service policies','People & teams','Canned responses'].map(t=><button className={tab===t?'selected':''} key={t} onClick={()=>setTab(t)}>{t}</button>)}</div>{tab==='Service policies'&&(settings?<form className="settings-form" onSubmit={save}><div className="settings-intro"><ShieldCheck size={24}/><div><h2>Clear commitments. Consistent service.</h2><p>Calendar changes apply to new requests. Existing deadlines keep their stored policy.</p></div></div><div className="sla-policy-grid">{tiers.map(t=><div key={t}><small>{tierInfo[t].name}</small><strong>{tierInfo[t].time}</strong><span>{['ELITE','PRIORITY'].includes(t)?'Continuous clock':'Business hours'}</span></div>)}</div><h3>Business calendar</h3><div className="form-two"><label className="field">IANA timezone<input required value={settings.calendar.zone} onChange={e=>setSettings({...settings,calendar:{...settings.calendar,zone:e.target.value}})}/></label><label className="field">Working days (1 = Monday)<input required value={settings.calendar.days.join(',')} onChange={e=>setSettings({...settings,calendar:{...settings.calendar,days:e.target.value.split(',').map(Number)}})}/></label><label className="field">Opening time<input type="time" required value={settings.calendar.open} onChange={e=>setSettings({...settings,calendar:{...settings.calendar,open:e.target.value}})}/></label><label className="field">Closing time<input type="time" required value={settings.calendar.close} onChange={e=>setSettings({...settings,calendar:{...settings.calendar,close:e.target.value}})}/></label></div><label className="field">Holidays (YYYY-MM-DD, comma-separated)<input value={settings.calendar.holidays.join(',')} onChange={e=>setSettings({...settings,calendar:{...settings.calendar,holidays:e.target.value.split(',').map((v:string)=>v.trim()).filter(Boolean)}})}/></label><h3>Routing and lifecycle</h3><div className="form-two">{[['warningMinutes','Warning before deadline (minutes)'],['agingMinutes','Queue aging threshold (minutes)'],['autoCloseHours','Close resolved tickets after (hours)']].map(([key,label])=><label className="field" key={key}>{label}<input type="number" min={key==='autoCloseHours'?0:1} value={settings[key]} onChange={e=>setSettings({...settings,[key]:Number(e.target.value)})}/></label>)}<label className="field">Optional resolution target (elapsed minutes)<input type="number" min={1} placeholder="No resolution SLA" value={settings.resolutionMinutes??''} onChange={e=>setSettings({...settings,resolutionMinutes:e.target.value?Number(e.target.value):null})}/></label></div><label className="check-field"><input type="checkbox" checked={settings.pauseResolutionOnWaitingCustomer} onChange={e=>setSettings({...settings,pauseResolutionOnWaitingCustomer:e.target.checked})}/>Pause resolution clock while waiting for customer</label><label className="field">Request categories<input required value={settings.categories.join(', ')} onChange={e=>setSettings({...settings,categories:e.target.value.split(',').map((v:string)=>v.trim()).filter(Boolean)})}/></label><button className="button primary" disabled={busy} type="submit"><Check size={16}/>{busy?'Saving…':'Save service policies'}</button></form>:<Empty title="Policies stay consistent across your workspace." body="Connect the service to configure calendars, routing, escalation, and closure." icon={Settings}/>)}
 {tab==='People & teams'&&<div className="settings-form"><div className="panel-heading"><h2>Workspace members</h2><button className="button" disabled={!online} onClick={()=>setCreate('member')}><Plus size={15}/>Add member</button></div>{data?.members?.map((m:AnyData)=><div className="admin-member" key={m.id}><span className="avatar">{initials(m.user.name)}</span><div><strong>{m.user.name}</strong><small>{m.user.email}</small></div><select aria-label={'Role for '+m.user.name} value={m.role} onChange={e=>{if(window.confirm('Change '+m.user.name+'’s service role?'))api('admin/members/'+m.id,{method:'PATCH',body:JSON.stringify({role:e.target.value})}).then(()=>reload()).catch(e=>notice(e.message));}}>{['CUSTOMER','AGENT','SUPERVISOR','ADMIN'].map(r=><option key={r}>{r}</option>)}</select><select aria-label={'Tier for '+m.user.name} value={m.tier} onChange={e=>api('admin/members/'+m.id,{method:'PATCH',body:JSON.stringify({tier:e.target.value})}).then(()=>reload()).catch(e=>notice(e.message))}>{tiers.map(r=><option key={r}>{r}</option>)}</select><input type="number" min={1} max={30} aria-label={'Capacity for '+m.user.name} defaultValue={m.capacity} onBlur={e=>{if(Number(e.target.value)!==m.capacity)api('admin/members/'+m.id,{method:'PATCH',body:JSON.stringify({capacity:Number(e.target.value)})}).then(()=>reload()).catch(e=>notice(e.message));}}/></div>)}{!data?.members?.length&&<Empty title="Your team belongs here." body="Members are provisioned with explicit roles and support entitlements." icon={Users}/>}<div className="panel-heading"><h3>Teams</h3><button className="button" disabled={!online} onClick={()=>setCreate('team')}><Plus size={14}/>Create team</button></div>{data?.teams?.map((t:AnyData)=><Tag key={t.id}>{t.name}</Tag>)}</div>}
 {tab==='Canned responses'&&<div className="settings-form"><div className="settings-intro"><MessageSquare size={24}/><div><h2>A useful starting point for replies.</h2><p>Human agents can insert saved responses into a conversation and edit before sending.</p></div></div><button className="button" disabled={!online} onClick={()=>setCreate('canned')}><Plus size={16}/>Create a response</button></div>}
 {create==='canned'&&<ContentForm title="New canned response" onClose={()=>setCreate('')} onSave={async v=>{await api('canned',{method:'POST',body:JSON.stringify(v)});setCreate('');notice('Response saved.');}}/>}
 {create==='team'&&<Modal title="Create a team" onClose={()=>setCreate('')}><form className="ticket-form" onSubmit={async e=>{e.preventDefault();try{await api('admin/teams',{method:'POST',body:JSON.stringify({name:String(new FormData(e.currentTarget).get('name'))})});await reload();setCreate('');}catch(e){notice((e as Error).message);}}}><label className="field">Team name<input name="name" required minLength={2}/></label><button className="button primary" type="submit">Create team</button></form></Modal>}
 {create==='member'&&<Modal title="Add a workspace member" subtitle="Use the person’s Site-scoped identity ID from their authenticated account." onClose={()=>setCreate('')}><form className="ticket-form" onSubmit={async e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.currentTarget));try{await api('admin/invitations',{method:'POST',body:JSON.stringify(values)});await reload();setCreate('');}catch(e){notice((e as Error).message);}}}>{[['name','Name'],['email','Email'],['externalId','Site identity ID']].map(([k,label])=><label className="field" key={k}>{label}<input name={k} required type={k==='email'?'email':'text'}/></label>)}<div className="form-two"><label className="field">Role<select name="role">{['CUSTOMER','AGENT','SUPERVISOR','ADMIN'].map(r=><option key={r}>{r}</option>)}</select></label><label className="field">Support tier<select name="tier">{tiers.map(r=><option key={r}>{r}</option>)}</select></label></div><button className="button primary" type="submit">Add member</button></form></Modal>}
 </div>;
}
